/**
 * The web client as a static site for Vercel, with everything dynamic
 * forwarded to a BluckFlies server elsewhere (for a test: this PC through an
 * ngrok tunnel). See docs/TUNNEL-TEST.md. Two ways to deploy:
 *
 * From GitHub (Vercel builds every push): the repository's vercel.json runs
 *   npm run build:web -- --from-env
 * which reads the server address from the Vercel environment variable
 * BLUCKFLIES_API_URL. That vercel.json is generated by gitVercelConfig() below
 * (npm run build:web -- --write-vercel-json) and checked by a test.
 *
 * From this PC (upload a folder):
 *   npm run build:web -- --api https://<name>.ngrok-free.app [--site https://<project>.vercel.app]
 * then `npx vercel deploy --prod` inside web-dist/.
 *
 * Output: web-dist/ with
 *   - index.html and desk.html, their links pointing at /v/<fingerprint>/…
 *     (same scheme as the server: a new build never mixes with cached files);
 *   - every public file under /v/<fingerprint>/ (cached for a year) and at its
 *     plain path (icons, manifest);
 *   - (upload only) vercel.json: security headers like the server's, and
 *     routes that send /api, the e-ticket links and the legal pages to --api,
 *     adding the ORIGIN_SECRET header (a Vercel environment variable).
 */
import { createHash } from 'node:crypto';
import { cp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { ORIGIN_SECRET_HEADER, SECURITY_HEADERS as SERVER_HEADERS } from './middleware.js';
import { fillSiteAddress, versionAssetLinks } from './webClient.js';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));
const PUBLIC_DIR = join(ROOT, 'public');
const OUT_DIR = join(ROOT, 'web-dist');
const PAGES = ['index.html', 'desk.html'];

/** Paths the BluckFlies server answers (everything else is a static file). */
export const SERVER_PATHS = '/(api/.*|e/.*|terms|privacy|refunds|healthz|readyz)';

/** The server's security headers, plus HSTS (Vercel serves HTTPS only). */
export const SECURITY_HEADERS: Record<string, string> = {
  ...SERVER_HEADERS,
  'strict-transport-security': 'max-age=31536000; includeSubDomains',
};

/** The address of the BluckFlies server: an https origin, nothing after it. */
export function serverOrigin(value: string, name: string): string {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    throw new Error(`${name} must be an address like https://name.ngrok-free.app (got "${value}")`);
  }
  if (url.protocol !== 'https:') throw new Error(`${name} must be an https:// address`);
  if (url.pathname !== '/' || url.search || url.hash) throw new Error(`${name} must be just the origin, e.g. https://name.ngrok-free.app`);
  return url.origin;
}

export type BuildOptions =
  /** Folder upload: routes to this address are written into web-dist/vercel.json. */
  | { mode: 'upload'; api: string; site: string }
  /** Git build on Vercel: the repository's vercel.json routes via BLUCKFLIES_API_URL. */
  | { mode: 'git'; api: string; site: string };

export const API_ENV = 'BLUCKFLIES_API_URL';

export function parseArgs(argv: string[], env: NodeJS.ProcessEnv = process.env): BuildOptions {
  const value = (flag: string): string | undefined => {
    const i = argv.indexOf(flag);
    return i >= 0 ? argv[i + 1] : undefined;
  };
  if (argv.includes('--from-env')) {
    const api = env[API_ENV];
    if (!api) throw new Error(`Set ${API_ENV} in the Vercel project (Settings → Environment Variables), e.g. https://name.ngrok-free.app, then redeploy`);
    // Vercel provides the production host name (without https://) to every build.
    const host = env['VERCEL_PROJECT_PRODUCTION_URL'];
    return { mode: 'git', api: serverOrigin(api, API_ENV), site: host ? `https://${host}` : '' };
  }
  const api = value('--api');
  if (!api) throw new Error('Missing --api https://<name>.ngrok-free.app (the address of the BluckFlies server), or --from-env on Vercel');
  const site = value('--site') ?? '';
  if (site && new URL(site).protocol !== 'https:') throw new Error('--site must be an https:// address');
  return { mode: 'upload', api: serverOrigin(api, '--api'), site: site.replace(/\/+$/, '') };
}

/** Routes: security headers on everything, the server's paths forwarded with the origin secret, then the files. */
function routes(dest: string, destEnv: string[]): Array<Record<string, unknown>> {
  return [
    { src: '/(.*)', headers: SECURITY_HEADERS, continue: true },
    { src: '/v/(.*)', headers: { 'Cache-Control': 'public, max-age=31536000, immutable' }, continue: true },
    { src: '/(|index\\.html|desk\\.html)', headers: { 'Cache-Control': 'no-cache' }, continue: true },
    {
      src: SERVER_PATHS,
      dest: `${dest}/$1`,
      ...(destEnv.length ? { env: destEnv } : {}),
      // Answers are per traveller: never cached by Vercel's CDN.
      headers: { 'x-vercel-enable-rewrite-caching': '0' },
      transforms: [
        // Proves to the server that the request came through this proxy (ORIGIN_SECRET on both sides).
        { type: 'request.headers', op: 'set', target: { key: ORIGIN_SECRET_HEADER }, args: '$ORIGIN_SECRET', env: ['ORIGIN_SECRET'] },
        // ngrok's free plan otherwise answers browser requests with its own warning page.
        { type: 'request.headers', op: 'set', target: { key: 'ngrok-skip-browser-warning' }, args: '1' },
      ],
    },
    { handle: 'filesystem' },
  ];
}

/** web-dist/vercel.json for a folder upload: the server address written in. */
export function vercelConfig(api: string): Record<string, unknown> {
  return { $schema: 'https://openapi.vercel.sh/vercel.json', routes: routes(api, []) };
}

/**
 * The repository's vercel.json, for deploys from GitHub. `framework: null`
 * ("Other") stops Vercel treating the Express server as the thing to deploy;
 * only web-dist/ is published. The server address comes from BLUCKFLIES_API_URL
 * when each request is forwarded, so it is never in the repository.
 */
export function gitVercelConfig(): Record<string, unknown> {
  return {
    $schema: 'https://openapi.vercel.sh/vercel.json',
    framework: null,
    installCommand: 'npm ci',
    buildCommand: 'npm run build:web -- --from-env',
    outputDirectory: 'web-dist',
    routes: routes(`\${${API_ENV}}`, [API_ENV]),
  };
}

export const ROOT_VERCEL_JSON = join(ROOT, 'vercel.json');

async function contentFingerprint(dir: string): Promise<string> {
  const entries = await readdir(dir, { withFileTypes: true, recursive: true });
  const files = entries.filter((e) => e.isFile()).map((e) => join(e.parentPath, e.name)).sort();
  const hash = createHash('sha256');
  for (const file of files) hash.update(`${relative(dir, file)}\0`).update(await readFile(file)).update('\n');
  return hash.digest('hex').slice(0, 12);
}

export async function buildWeb(argv: string[], outDir = OUT_DIR, env: NodeJS.ProcessEnv = process.env): Promise<{ outDir: string; fingerprint: string; api: string; mode: BuildOptions['mode'] }> {
  const { mode, api, site } = parseArgs(argv, env);
  const fingerprint = await contentFingerprint(PUBLIC_DIR);
  // Start clean, but keep .vercel/ (the link to the Vercel project made by `vercel link`).
  await mkdir(outDir, { recursive: true });
  for (const entry of await readdir(outDir)) {
    if (entry !== '.vercel') await rm(join(outDir, entry), { recursive: true, force: true });
  }
  await cp(PUBLIC_DIR, outDir, { recursive: true });
  await cp(PUBLIC_DIR, join(outDir, 'v', fingerprint), { recursive: true });
  for (const page of PAGES) {
    const html = await readFile(join(PUBLIC_DIR, page), 'utf8');
    await writeFile(join(outDir, page), fillSiteAddress(versionAssetLinks(html, fingerprint), site));
  }
  // A Git build uses the repository's vercel.json; a folder upload carries its own.
  if (mode === 'upload') await writeFile(join(outDir, 'vercel.json'), `${JSON.stringify(vercelConfig(api), null, 2)}\n`);
  return { outDir, fingerprint, api, mode };
}

export async function writeGitVercelConfig(path = ROOT_VERCEL_JSON): Promise<void> {
  await writeFile(path, `${JSON.stringify(gitVercelConfig(), null, 2)}\n`);
}
